import {quantumCurveSVG} from './quantum-plots.js?v=20261031-entry2';
import {crystalSpan} from './crystal-notation.js?v=20261031-entry2';
import {mathHTML} from './math-display.js?v=20261031-entry2';
import {captureCalculation,RELEASE} from './material-notebook.js?v=20261031-entry2';

const KEY='symmetry-lab.shg-flagship.progress.v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>Number.isFinite(x)?Number(x.toPrecision(5)):'—';
const formula=tex=>`<div class="shg-equation sl-math" data-math-source="${esc(tex)}">${mathHTML(tex,true)}</div>`;
export const SHG_MATERIALS=[
 {id:'si',title:'Si · 金刚石结构',model:'centrosymmetric',group:'O_h',hm:'m-3m',phase:'体相、未应变的理想金刚石结构',coefficients:{},cOverA:1},
 {id:'gaas',title:'GaAs · 闪锌矿',model:'gaas',group:'T_d',hm:'-43m',phase:'体相闪锌矿结构',coefficients:{xyz:1},cOverA:1},
 {id:'bto',title:'BaTiO₃ · 四方铁电相',model:'batio3',group:'C_{4v}',hm:'4mm',phase:'单畴、极轴沿晶体 z；不代表立方顺电相',coefficients:{xxz:1,zxx:.7,zzz:1.5},cOverA:1.01}
];
export const shgInput=(material,geometry)=>({model:material.model,coefficients:{...material.coefficients},cOverA:material.cOverA,cut:geometry.cut,incidence:geometry.incidence,azimuth:geometry.azimuth,channel:geometry.channel,samples:73});
let latest=null;
export const getSHGFlagshipResult=()=>latest;
const curve=(records,channel)=>quantumCurveSVG(records.map(r=>({label:r.label,points:r.result.scan.angles.map((a,i)=>[a,r.result.scan.channels[channel].intensities[i]])})),{xLabel:'方位角 φ（°）',yLabel:'SHG 强度（共同任意单位）'});
const table=(heads,rows)=>`<div class="shg-table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const choice=(id,value,options)=>`<select id="${id}"><option value="">请先判断</option>${options.map(([v,label])=>`<option value="${v}" ${value===v?'selected':''}>${label}</option>`).join('')}</select>`;

export function renderSHGFlagship({container,run,cancelRun,download,toast=()=>{}}){
 latest=null;
 let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch{}
 const predictions=Object.fromEntries(SHG_MATERIALS.map(m=>[m.id,['allowed','forbidden'].includes(saved.predictions?.[m.id])?saved.predictions[m.id]:'']));
 let predicted=Boolean(saved.predicted)&&Object.values(predictions).every(Boolean),explanation=String(saved.explanation||'').slice(0,4000),conclusion=String(saved.conclusion||'').slice(0,4000),counterPrediction=['yes','no'].includes(saved.counterPrediction)?saved.counterPrediction:'';
 let geometry={cut:'001',incidence:45,azimuth:30,channel:'PP'},records=[],counter=[],conceptPassed=false,completed=false,busy=false,ticket=0,status='',q1='',q2='',inference='';
 container.innerHTML='<article class="shg-story"></article>';const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>container.isConnected!==false&&root.parentNode===container;
 const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify({predictions,predicted,explanation,conclusion,counterPrediction}));}catch{status='浏览器未保存草稿；可在完成后导出报告。';}};
 const clearCompletion=()=>{completed=false;latest=null;if($('#shg-completion'))$('#shg-completion').innerHTML='';};
 const report=()=>({format:'symmetry-lab-shg-flagship',version:1,release:RELEASE,created:new Date().toISOString(),scope:'理想体相、电偶极 SHG、简并输入频率、只施加 j↔k 对称；教学系数和共同任意强度单位。',geometry:{...geometry},predictions:{...predictions},calculations:records,counterPrediction,counterexamples:counter,explanation,conclusion,assessment:{conceptPassed,completed,freeText:'文字已记录，未作自动物理正确性判分。'}});
 const remember=()=>{const last=counter.at(-1);if(!last)return;const result={...last.result,learningEvidence:{flagship:report()}};latest={tool:'shg_lab',input:last.input,result};captureCalculation('shg_lab',last.input,result,{route:'compute/shg-flagship',title:'Si / GaAs / BaTiO₃ · SHG 旗舰实验报告',material:'Si; GaAs; tetragonal BaTiO3'});};
 function invalidate(){records=[];counter=[];conceptPassed=false;completed=false;latest=null;status='几何参数已改变，请重新计算并核对解释。';}
 async function calculate(kind){
  if(busy||!predicted||kind==='counter'&&(!conceptPassed||!counterPrediction))return;
  const request=++ticket;busy=true;completed=false;latest=null;status='正在启动浏览器内 Python；首次加载可能需要一些时间…';draw();
  const active=()=>current()&&ticket===request;
  try{
   const inputs=kind==='main'?SHG_MATERIALS.map(m=>({id:m.id,label:m.title,input:shgInput(m,geometry)})):[0,45].map(theta=>({id:String(theta),label:'GaAs (001) · 入射 '+theta+'°',input:shgInput(SHG_MATERIALS[1],{cut:'001',incidence:theta,azimuth:30,channel:'PP'})}));
   const results=[];
   for(const item of inputs){if(!active())return;status='正在计算 '+item.label+'…';$('#shg-status').textContent=status;const result=await run('shg_lab',item.input);if(!active())return;results.push({...item,result});}
   if(kind==='main'){records=results;counter=[];conceptPassed=false;}else counter=results;
   status=kind==='main'?'三种材料计算完成。先比较预测与结果，再完成解释。':'反例计算完成。检查“是否有反演”与“是否测到信号”是否等价。';
  }catch(error){if(active())status='计算未完成：'+error.message+'。可重试，当前页面保留你的判断与笔记。';}
  finally{if(active()){busy=false;draw();}}
 }
 function draw(){
  if(!current())return;
  root.innerHTML=`<header class="shg-intro"><span class="obs-eyebrow">旗舰实验 · 建议 25–35 分钟</span><h2>没有 SHG 信号，就一定有反演对称吗？</h2><p>用 Si、GaAs 和四方 BaTiO₃，完成一次“提出预测—计算证据—解释机制—反例验证”的完整实验。</p><p>建议基础：点群、反演操作、向量与矩阵。完成后你应能区分张量被禁止、张量被允许和某个测量通道出现信号。</p><div class="shg-stages" aria-label="实验进度">${[['预测',predicted],['计算',records.length===3],['解释',conceptPassed],['反例',completed]].map(([name,done],i)=>`<span class="${done?'done':''}">${i+1} · ${name}${done?' ✓':''}</span>`).join('')}</div></header>
  <aside class="shg-scope"><strong>这个实验计算什么？</strong><p>理想体相的电偶极二次谐波响应。Si 的表面、界面、电四极等贡献不在本模型中。BaTiO₃ 固定为四方单畴铁电相；三种材料使用教学系数，不能据此比较真实材料的绝对 SHG 效率。</p><p>草稿在本浏览器保存；刷新或离开后需重算结果。完成后可导出全部数值与解释。</p></aside>
  <section class="shg-step"><h3>1 · 先预测：哪一种体相允许电偶极 SHG？</h3><p>“允许”只表示对称性没有强制所有二阶张量分量为零。先独立判断，后面会保留你的原始选择。</p><div class="shg-materials">${SHG_MATERIALS.map(m=>`<article><h4>${m.title}</h4><p>${mathHTML(m.group)}（${crystalSpan(m.hm)}） · ${m.phase}</p><label><span>我的预测</span>${choice('shg-p-'+m.id,predictions[m.id],[['forbidden','对称性禁止'],['allowed','对称性允许']])}</label></article>`).join('')}</div><button id="shg-predict" class="primary" ${predicted?'disabled':''}>${predicted?'预测已记录':'记录预测，开始计算'}</button><p>预测不一致也是学习证据；无需先答对才能继续。</p></section>
  <section class="shg-step"><h3>2 · 算一遍：从张量约束到偏振信号</h3><div class="shg-controls"><label><span>晶面</span><select id="shg-cut">${['001','111'].map(v=>`<option value="${v}" ${geometry.cut===v?'selected':''}>(${v})</option>`).join('')}</select></label><label><span>入射角 θ（°，相对表面法线）</span><input id="shg-incidence" type="number" min="0" max="85" step="1" value="${geometry.incidence}"></label><label><span>方位角 φ（°）</span><input id="shg-azimuth" type="number" min="0" max="360" step="1" value="${geometry.azimuth}"></label><label><span>偏振通道（入射 → 出射）</span><select id="shg-channel">${['PP','PS','SP','SS'].map(v=>`<option value="${v}" ${geometry.channel===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p>P 在入射面内，S 垂直入射面；入射面为实验室 xz 平面。曲线扫描方位角，表格显示所选角度。所有曲线共用任意单位，未逐条归一化。</p><details><summary>教学系数与晶轴约定</summary><p>GaAs：χ_{xyz} = 1（所有不同指标的排列相等）。BaTiO₃：χ_{xxz} = χ_{xzx} = χ_{yyz} = χ_{yzy} = 1，χ_{zxx} = χ_{zyy} = 0.7，χ_{zzz} = 1.5，c/a = 1.01。Si：全部分量为 0。BaTiO₃ 不施加 Kleinman 全排列对称。</p><p>(001) 初始晶轴与实验室轴对齐；(111) 按既有 SHG 核心的晶面法线构造初始取向。实际取向矩阵保存在报告中。忽略 Fresnel 因子、吸收、相位匹配和表面贡献。</p></details><button id="shg-calculate" class="primary" ${!predicted||busy?'disabled':''}>计算三种材料</button><button id="shg-cancel" class="secondary" ${busy?'':'hidden'}>取消本轮计算</button><p id="shg-status" role="status" aria-live="polite">${esc(status||'请先记录三种材料的预测。')}</p><div id="shg-results">${records.length===3?table(['材料','原始预测','含反演','独立分量数','当前强度','预测核对'],records.map(r=>[esc(r.label),predictions[r.id]==='allowed'?'允许':'禁止',r.result.symmetry.inversionPresent?'是':'否',r.result.tensor.dimension,num(r.result.selection.intensity),(r.result.tensor.dimension>0)===(predictions[r.id]==='allowed')?'一致':'需要修正']))+curve(records,geometry.channel)+`<details><summary>查看群投影与张量基的原始证据</summary>${records.map(r=>`<h4>${esc(r.label)}</h4><p>群投影给出的维数：${r.result.symmetry.dimensionFromGroupProjector}；协变残差：${num(r.result.symmetry.covarianceResidual)}。</p><pre>${esc(JSON.stringify(r.result.tensor.basis,null,2))}</pre>`).join('')}</details>`:''}</div></section>
  <section class="shg-step"><h3>3 · 解释：为什么得到 0、1、3 个独立分量？</h3><p>先完成计算，再逐步展开推导，写出你自己的解释。</p><details><summary>推导 ① · 反演如何约束奇阶极性张量</summary>${formula(String.raw`P_i(2\omega)=\varepsilon_0\sum_{jk}\chi^{(2)}_{ijk}E_j(\omega)E_k(\omega)`)}<p>反演下极化和电场都反号，而两个电场的乘积不变。若材料在反演下不变，同一个响应系数必须满足：</p>${formula(String.raw`\chi^{(2)}=-\chi^{(2)}\quad\Longrightarrow\quad\chi^{(2)}=0`)}<p>因此理想体相 Si 的电偶极 SHG 被禁止；这不排除它的表面 SHG。</p></details><details><summary>推导 ② · 群投影保留哪些张量分量</summary>${formula(String.raw`\Pi=\frac{1}{|G|}\sum_{R\in G}R\otimes R\otimes R`)}<p>在最后两个指标交换对称的张量空间上求不变子空间。Oh、Td 和 C4v 分别给出 0、1、3 维；无反演只是排除了反演这一项禁戒，还需检查完整点群。</p></details><details><summary>推导 ③ · 为什么“允许”不保证这个通道非零</summary>${formula(String.raw`A=\mathbf e_{\mathrm{out}}\cdot\mathbf P(2\omega),\qquad I\propto |A|^2`)}<p>非线性极化还要投影到探测偏振。几何、偏振和分量间相消都可能让振幅为零。这里采用单位入射场，并将共同常数吸收进任意强度单位。</p></details><div class="shg-controls"><label><span>反演约束施加在哪里？</span>${choice('shg-q1',q1,[['tensor','所有体相电偶极二阶张量分量'],['channel','只约束 PP 通道']])}</label><label><span>一个允许的张量意味着什么？</span>${choice('shg-q2',q2,[['possible','存在对称性允许的非零响应分量'],['always','任意几何、任意通道都必定有信号']])}</label></div><label><span>我的解释：用“反演—张量—测量投影”连接三种材料的差异</span><textarea id="shg-explanation" rows="4" maxlength="4000">${esc(explanation)}</textarea></label><button id="shg-explain" class="primary" ${records.length!==3||busy?'disabled':''}>核对概念并保存解释</button><p id="shg-explanation-status">${conceptPassed?'概念自测已通过。文字已记录，请对照推导自行核查或交由教师评阅。':''}</p></section>
  <section class="shg-step"><h3>4 · 反例验证：保持 GaAs 点群，改变测量几何</h3><p>固定 GaAs (001)、同一非零张量和 φ = 30°，分别计算正入射 θ = 0° 与斜入射 θ = 45°。先预测，再运行。</p><label><span>如果正入射时所有偏振通道都为零，能否据此断言材料有反演？</span>${choice('shg-counter-prediction',counterPrediction,[['yes','能，零信号说明有反演'],['no','不能，还须排除几何与投影的影响']])}</label><button id="shg-counter" class="primary" ${!conceptPassed||!counterPrediction||busy?'disabled':''}>计算并对照两个几何</button><div id="shg-counter-results">${counter.length===2?table(['几何','含反演','独立分量数','PP 当前强度','四通道扫描最大值'],counter.map(r=>[esc(r.label),r.result.symmetry.inversionPresent?'是':'否',r.result.tensor.dimension,num(r.result.selection.intensity),num(Math.max(...Object.values(r.result.scan.channels).flatMap(c=>c.intensities)))]))+curve(counter,'PP')+`<details><summary>分步解释这个反例</summary><p>① 两次计算的晶体、群操作和张量完全相同，均无反演且独立分量数为 1。</p><p>② 正入射时入射电场在 xy 平面。GaAs 的非零分量要求三个指标不同，产生的极化沿 z，无法投影到横向探测偏振；四通道均为零。</p><p>③ 斜入射引入沿 z 的偏振分量及不同的出射投影，至少一个通道出现信号。改变的是测量几何，材料的点群没有改变。</p><p>④ 因而单个零信号不足以反推反演。真实实验还需考虑探测灵敏度、表面与其他多极贡献。</p></details>`:''}</div><label><span>核对后的结论</span>${choice('shg-inference',inference,[['geometry','零信号不足以判定反演；需检查几何、通道和模型适用条件'],['inversion','GaAs 在正入射时变成有反演的材料']])}</label><label><span>报告结论：引用一个数值，并说明什么证据会改变你的判断</span><textarea id="shg-conclusion" rows="4" maxlength="4000">${esc(conclusion)}</textarea></label><button id="shg-complete" class="primary" ${counter.length!==2||busy?'disabled':''}>完成实验并生成证据报告</button><div id="shg-completion">${completed?'<p class="shg-success">四阶段证据已齐全。概念题已核对；开放解释由你或教师评阅。</p><button id="shg-export" class="secondary">导出完整实验 JSON</button><a href="#atlas/notebook">打开材料研究记录并加入本次报告 →</a>':''}</div></section>
  <footer class="shg-step"><h3>继续追问</h3><button id="shg-restart" class="secondary" ${busy?'disabled':''}>重新开始本实验（清空草稿）</button><p>开始新一轮前，请先导出需要保留的报告。此按钮只清空本实验草稿，不删除材料研究记录。</p><p>项目作业：在完整 SHG 计算器中改变 BaTiO₃ 的 χ_{zzz}，保持点群不变。比较 PP 与 SS，说明“系数变化”和“对称性变化”有什么区别，并把结果加入同一材料项目。</p><div class="shg-links"><a href="#compute/shg-lab">完整 SHG 计算器</a><a href="#compute/tensors">物性张量约束</a><a href="#atlas">材料图谱</a><a href="#classroom/crystal?tab=materials&material=silicon">Si 晶体结构课堂</a><a href="#classroom/crystal?tab=materials&material=gaas">GaAs 晶体结构课堂</a></div><p>方法延伸：<a href="https://bfichera.github.io/shgpy/" target="_blank" rel="noopener">ShgPy 的旋转各向异性 SHG 教程</a>；<a href="https://wiki.yambo-code.eu/wiki/index.php?title=Angular_dependence_of_non-linear_response" target="_blank" rel="noopener">Yambo 的非线性响应角依赖教程</a>。本站运行既有 Python 教学核心，不调用这两个外部程序。</p></footer>`;
  for(const m of SHG_MATERIALS){const input=$('#shg-p-'+m.id);input.disabled=predicted||busy;input.onchange=()=>{predictions[m.id]=input.value;persist();};}
  $('#shg-predict').onclick=()=>{if(Object.values(predictions).some(x=>!x)){status='请先为三种材料都选择一个预测。';draw();return;}predicted=true;persist();status='预测已保留，可以开始计算。';draw();};
  for(const key of ['cut','incidence','azimuth','channel']){const input=$('#shg-'+key);input.disabled=busy;input.onchange=()=>{const value=['incidence','azimuth'].includes(key)?Number(input.value):input.value;if(['incidence','azimuth'].includes(key)&&(!Number.isFinite(value)||input.value.trim()===''||value<0||value>(key==='incidence'?85:360))){status='请输入范围内的角度。';draw();return;}geometry[key]=value;invalidate();draw();};}
  $('#shg-calculate').onclick=()=>calculate('main');$('#shg-counter').onclick=()=>calculate('counter');
  $('#shg-cancel').onclick=()=>{++ticket;busy=false;cancelRun?.();status='本轮已取消；未完成的结果不会作为实验依据。';draw();};
  $('#shg-q1').onchange=e=>{q1=e.target.value;conceptPassed=false;clearCompletion();if($('#shg-counter'))$('#shg-counter').disabled=true;};$('#shg-q2').onchange=e=>{q2=e.target.value;conceptPassed=false;clearCompletion();if($('#shg-counter'))$('#shg-counter').disabled=true;};
  $('#shg-explanation').oninput=e=>{explanation=e.target.value.slice(0,4000);clearCompletion();persist();};
  $('#shg-explain').onclick=()=>{conceptPassed=q1==='tensor'&&q2==='possible'&&Boolean(explanation.trim());status=conceptPassed?'概念核对通过；现在检验 GaAs 的几何反例。':'请结合三个推导步骤重新核对概念，并写下自己的解释。';persist();draw();};
  $('#shg-counter-prediction').disabled=counter.length>0||busy;$('#shg-counter-prediction').onchange=e=>{counterPrediction=e.target.value;persist();draw();};
  $('#shg-inference').onchange=e=>{inference=e.target.value;clearCompletion();};$('#shg-conclusion').oninput=e=>{conclusion=e.target.value.slice(0,4000);clearCompletion();persist();};
  $('#shg-complete').onclick=()=>{completed=records.length===3&&counter.length===2&&conceptPassed&&inference==='geometry'&&Boolean(conclusion.trim())&&Boolean(explanation.trim());status=completed?'已生成完整实验报告。':'请核对结论，并填写有数值依据的解释；无需修改原始预测。';persist();if(completed)remember();draw();};
  if($('#shg-export'))$('#shg-export').onclick=()=>{if(!completed){toast('解释已更改，请重新完成实验。');return;}download(JSON.stringify(report(),null,2),'shg-flagship-report.json','application/json');};
  $('#shg-restart').onclick=()=>{if(busy)return;for(const m of SHG_MATERIALS)predictions[m.id]='';predicted=false;explanation=conclusion=counterPrediction=q1=q2=inference='';geometry={cut:'001',incidence:45,azimuth:30,channel:'PP'};invalidate();status='已开始新一轮实验，请重新记录预测。';persist();draw();};
  if(busy)for(const tag of ['select','textarea'])root.querySelectorAll(tag).forEach(el=>el.disabled=true);
 }
 draw();
}
